#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14c: Content in the admin dashboard
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part, Content in the dashboard's sidebar is live:
#   * Videos: every video with its owner, who can see it, views and size;
#     search by title, id or owner; All, Public, Unlisted, Private, Taken
#     down; a review page that plays the video, with its summary and chapters
#   * Take down (a reason is needed) and Restore. A video taken down opens
#     only for its owner, who sees VideoMind's reason; everyone else is told
#     "This video was removed". It leaves the shared page, captions, previews,
#     Ask, view counts, the public profile and Continue watching, and cannot
#     be published to YouTube. Copies on Shelby or YouTube stay
#   * Live events: every event with its host; End now
#   * YouTube uploads: every upload with a link to it
#   * each action is written to the audit log
#
#   BACKEND    1 new file, 11 changed. Migration 021_removals (runs by itself)
#   DASHBOARD  2 new files, 3 changed. No packages
#   FRONTEND   3 changed. No packages
#
#   ./vm_content.sh            apply (needs Part 14b on the branch)
#   ./vm_content.sh --force    apply even if local files differ from GitHub
#   ./vm_content.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_content"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_content_backups"

ADD=(
  "backend/src/lib/adminContent.ts"
  "dashboard/src/app/(admin)/content/page.tsx"
  "dashboard/src/app/(admin)/content/videos/[id]/page.tsx"
)
MOD=(
  "backend/src/routes/admin.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/lib/store.ts"
  "backend/src/lib/videoInfo.ts"
  "backend/src/types/video.ts"
  "backend/src/routes/videos.ts"
  "backend/src/routes/chat.ts"
  "backend/src/routes/notes.ts"
  "backend/src/routes/profiles.ts"
  "backend/src/routes/progress.ts"
  "backend/src/routes/youtube.ts"
  "dashboard/src/lib/api.ts"
  "dashboard/src/components/Shell.tsx"
  "dashboard/src/app/(admin)/page.tsx"
  "frontend/src/lib/api.ts"
  "frontend/src/app/v/[id]/page.tsx"
  "frontend/src/app/video/[id]/page.tsx"
)
PRE_MOD=(
