B64_A2
verify "$TMPD/a2" "${NEW_ADD[2]}" "dashboard/src/app/(admin)/content/videos/[id]/page.tsx"

grep -q "$MARKER" "$TMPD/a0"                                   || die "adminContent.ts payload missing marker. Aborting."
grep -q 'export async function removeVideo' "$TMPD/a0"           || die "adminContent.ts payload is wrong. Aborting."
grep -q 'YouTube uploads' "$TMPD/a1"                             || die "content page payload is wrong. Aborting."
grep -q 'Take the video down' "$TMPD/a2"                         || die "review page payload is wrong. Aborting."
grep -q 'adminContent' "$TMPD/m0"                    || die "routes/admin.ts payload is wrong. Aborting."
grep -q 'vm_admin_users' "$TMPD/m0"                  || die "routes/admin.ts payload lost 14b. Aborting."
grep -q '021_removals' "$TMPD/m1"                  || die "migrations.ts payload missing 021. Aborting."
grep -q '020_suspensions' "$TMPD/m1"               || die "migrations.ts payload lost 020. Aborting."
grep -q 'removed_at' "$TMPD/m2"                         || die "store.ts payload is wrong. Aborting."
grep -q 'export const blockedFor' "$TMPD/m3"        || die "videoInfo.ts payload is wrong. Aborting."
grep -q 'export async function playbackOf' "$TMPD/m5" || die "videos.ts payload is wrong. Aborting."
grep -q 'deleteViewsForVideo' "$TMPD/m5"            || die "videos.ts payload lost 13b. Aborting."
grep -q 'code: "removed"' "$TMPD/m10"               || die "youtube.ts payload is wrong. Aborting."
grep -q 'getContentVideos' "$TMPD/m11"                   || die "dashboard api.ts payload is wrong. Aborting."
grep -q 'href: "/content"' "$TMPD/m12"         || die "Shell.tsx payload is wrong. Aborting."
grep -q 'data-removed-notice' "$TMPD/m16"    || die "video page payload is wrong. Aborting."
grep -q 'isRemoved' "$TMPD/m15"                  || die "shared page payload is wrong. Aborting."
say "20 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Content (Part 14c)."
say "Migration 021_removals runs when the backend starts. Nothing to install."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_content.sh --revert"
